"""Deterministic provider for offline development and automated tests."""

from ai_agent_platform.core.models import AgentDefinition, AgentRequest


class FakeProvider:
    """Predictable test double; this is not an actual language model."""

    @property
    def name(self) -> str:
        return "fake"

    def generate(self, agent: AgentDefinition, request: AgentRequest) -> str:
        task = " ".join(request.task.split())
        return (
            f"[FAKE:{agent.agent_id}] {agent.name} received task: {task}\n"
            "This response was generated by the deterministic test provider, not by an AI model."
        )
